# Kaggle kernel — coder-1 eğitimi (T4x2 veya P100, ~12s/oturum, ~30s/hafta).
#
# Kaggle'da "New Notebook" → kod hücrelerine sırayla:
#   !git clone <veya dataset yükle> coder-1
#   %cd coder-1
#   !pip install -r requirements.txt
# Bu dosya tek hücre olarak da çalışır: veri → tokenizer → pretrain → kaydet.
#
# Oturum sınırı: --ckpt_every 500 + --resume ile parça parça eğitim.
# Çıktılar /kaggle/working/ altına → oturum bitince "Save Version" ile saklanır.
#
# Aşağıdakiler Kaggle ortam değişkenleriyle doldurulur (bizim makinede değil):
#   C1_DATA_GB   = kaç MB ham metin toplansın (varsayılan 400)
#   C1_PRESET    = nano|mini|small  (varsayılan small — T4x2 hedefi)
#   C1_STEPS     = oturum başına adım (varsayılan 9000 — ~11s @ T4x2)
#   C1_RESUME    = "1" ise /kaggle/working/runs/<preset> içinden devam

import os
import subprocess
import sys

ROOT = "/kaggle/working/coder-1"

# teşhis: input ağacını her zaman bas
print("== /kaggle/input ==")
for dp, dn, fn in os.walk("/kaggle/input"):
    print(dp, dn[:6], fn[:6])
    if dp.count("/") > 2:
        dn.clear()

# kod script içinde gömülü (dataset bağımlılığı yok)
_SRC_B64 = ""
if not os.path.exists(ROOT):
    import io, tarfile, base64
    os.makedirs(ROOT, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(_SRC_B64)),
                      mode="r:gz") as t:
        t.extractall(ROOT)
print("kod açıldı:", os.listdir(ROOT))
DATA_GB = int(os.environ.get("C1_DATA_GB", "400"))
PRESET = os.environ.get("C1_PRESET", "mini")
STEPS = int(os.environ.get("C1_STEPS", "6000"))
RESUME = os.environ.get("C1_RESUME", "1") == "1"

sys.path.insert(0, ROOT)


def sh(cmd):
    print("+", cmd, flush=True)
    subprocess.run(cmd, shell=True, check=True, cwd=ROOT)


def main():
    os.chdir(ROOT)

    import torch
    print("torch", torch.__version__, "cuda build:", torch.version.cuda,
          "available:", torch.cuda.is_available(),
          "devices:", torch.cuda.device_count())
    if not torch.cuda.is_available():
        raise SystemExit(
            "GPU yok: hesap GPU kotası/doğrulaması eksik olabilir; "
            "CPU eğitimi bu kernel'ın amacı değil")
    DEVICE = "cuda"

    READY = "/kaggle/input/c1-data"
    V2 = "/kaggle/input/c1-data-v2"
    R1 = "/kaggle/input/c1-round1"
    R3 = "/kaggle/input/c1-round3"
    AUTO = "/kaggle/input/c1-auto"
    if os.path.exists(AUTO + "/cycle.json") and os.path.exists(AUTO + "/ckpt/model.pt"):
        import json as _j
        C = _j.load(open(AUTO + "/cycle.json"))
        print("otonom döngü", C)
        TK = V2 + "/tok16k"
        W = "/kaggle/working"
        if os.path.exists(AUTO + "/shards/index.json"):
            sh("python -m model.pretrain --preset mini --data " + AUTO + "/shards"
               " --tokenizer " + TK + " --out " + W + "/runs/auto/base"
               " --steps " + str(C["steps"]) + " --batch 8 --accum 8 --seq 512"
               " --lr " + str(C["lr"]) + " --warmup 100 --init_from " + AUTO + "/ckpt"
               " --device " + DEVICE)
            base = W + "/runs/auto/base/last"
        else:
            base = AUTO + "/ckpt"
        sh("python -m model.sft --ckpt " + base + " --data " + AUTO + "/sft_pool.jsonl"
           " --tokenizer " + TK + " --out " + W + "/runs/auto/sft"
           " --steps " + str(C["sft_steps"]) + " --batch 4 --accum 4 --seq 512 --lr 1e-4"
           " --device " + DEVICE)
        sh("python -m model.eval --ckpt " + W + "/runs/auto/sft/last --tokenizer " + TK +
           " --out " + W + "/eval_auto.json --device " + DEVICE)
        SP = ("python -m model.selfplay run --ckpt " + W + "/runs/auto/sft/last"
              " --tokenizer " + TK + " --device " + DEVICE)
        if os.path.exists(AUTO + "/eval_holdout.jsonl"):   # sınav seti: ölçüm, eğitime girmez
            subprocess.run(SP + " --holdout --tasks " + AUTO + "/eval_holdout.jsonl"
                           " --out " + W + "/eval_holdout.jsonl", shell=True, cwd=ROOT)
        if os.path.exists(AUTO + "/tasks.jsonl"):
            if os.path.exists(AUTO + "/task_stats.json"):
                import shutil as _sh
                _sh.copy(AUTO + "/task_stats.json", W + "/task_stats.json")
            subprocess.run(SP + " --tasks " + AUTO + "/tasks.jsonl --stats " + W + "/task_stats.json"
                           " --out " + W + "/selfplay_new.jsonl --k 4 --max_tasks 250",
                           shell=True, cwd=ROOT)
        return

    if os.path.exists(R3 + "/mini_v2/last/model.pt") and \
       os.path.exists(R1 + "/sft_v2.jsonl"):
        # Tur 4: Tur-3 ckpt'inden genişletilmiş SFT (sohbet + soru-sor ajan)
        print("tur 4: r3 ckpt + sft_v2 — genişletilmiş SFT")
        sh("python -m model.sft --ckpt " + R3 + "/mini_v2/last"
           " --data " + R1 + "/sft_v2.jsonl --tokenizer " + V2 + "/tok16k"
           " --out /kaggle/working/runs/sft"
           " --steps 1200 --batch 4 --accum 4 --seq 512 --lr 1e-4"
           " --device " + DEVICE)
        sh("python -m model.eval --ckpt /kaggle/working/runs/sft/last"
           " --tokenizer " + V2 + "/tok16k"
           " --out /kaggle/working/eval_sft.json --device " + DEVICE)
        return
    if os.path.exists(V2 + "/shards/index.json") and \
       os.path.exists(R1 + "/mini/last/model.pt"):
        # Tur 3: büyütülmüş korpus (135M tok) üzerinde Tur-1 ckpt'ten devam
        # pretrain → ardından SFT → eval
        print("tur 3: v2 shards + r1 ckpt bulundu — devam eğitimi + sft")
        sh("python -m model.pretrain --preset " + PRESET +
           " --data " + V2 + "/shards --tokenizer " + V2 + "/tok16k"
           " --out /kaggle/working/runs/mini_v2"
           " --steps " + str(STEPS) + " --batch 8 --accum 8 --seq 512 --lr 2e-4"
           " --ckpt_every 500 --sample_every 2000 --device " + DEVICE +
           " --init_from " + R1 + "/mini/last")
        sh("python -m model.sft --ckpt /kaggle/working/runs/mini_v2/last"
           " --data " + R1 + "/sft.jsonl --tokenizer " + V2 + "/tok16k"
           " --out /kaggle/working/runs/sft"
           " --steps 800 --batch 4 --accum 4 --seq 512 --lr 1e-4"
           " --device " + DEVICE)
        sh("python -m model.eval --ckpt /kaggle/working/runs/sft/last"
           " --tokenizer " + V2 + "/tok16k"
           " --out /kaggle/working/eval_sft.json --device " + DEVICE)
        return
    r1 = os.path.exists(R1 + "/mini/last/model.pt") and \
         os.path.exists(R1 + "/sft.jsonl")
    if r1:
        # Tur 2: Tur-1 checkpoint'inden SFT — ajan formatı öğretimi
        print("tur-1 checkpoint + sft.jsonl bulundu — SFT turu")
        sh("python -m model.sft --ckpt " + R1 + "/mini/last"
           " --data " + R1 + "/sft.jsonl --tokenizer " + READY + "/tok16k"
           " --out /kaggle/working/runs/sft"
           " --steps 800 --batch 4 --accum 4 --seq 512 --lr 1e-4"
           " --device " + DEVICE)
        sh("python -m model.eval --ckpt /kaggle/working/runs/sft/last"
           " --tokenizer " + READY + "/tok16k"
           " --out /kaggle/working/eval_sft.json --device " + DEVICE)
        return
    ready = os.path.exists(READY + "/shards/index.json") and \
            os.path.exists(READY + "/tok16k/vocab.json")
    if ready:
        print("hazır veri dataseti bulundu — kazıma/tokenizer/shard atlanıyor")
        sh("python -m model.pretrain --preset " + PRESET +
           " --data " + READY + "/shards --tokenizer " + READY + "/tok16k"
           " --out /kaggle/working/runs/" + PRESET +
           " --steps " + str(STEPS) + " --batch 8 --accum 8 --seq 512 --lr 3e-4"
           " --ckpt_every 500 --sample_every 2000 --device " + DEVICE +
           (" --resume" if RESUME else ""))
        sh("python -m model.eval --ckpt /kaggle/working/runs/" + PRESET +
           "/last --tokenizer " + READY + "/tok16k"
           " --out /kaggle/working/eval_" + PRESET + ".json --device " + DEVICE)
        return

    # 1) Veri: GitHub tarball küratörlü liste + code_search_net → raw.txt
    raw = "/kaggle/working/raw_code.txt"
    if not os.path.exists(raw):
        from model.data.sources import iter_repo_list
        from model.data.clean import looks_like_code
        total = 0
        with open(raw, "w") as f:
            for text in iter_repo_list("model/data/repos.txt", per_repo_files=500):
                if looks_like_code(text):
                    f.write(text + "\n\n")
                    total += len(text)
                    if total % (50 << 20) < len(text):
                        print(f"  {total>>20} MB")
                    if total >= DATA_GB << 20:
                        break
    print("veri hazır")

    # 2) Tokenizer: gerçek corpus üzerinde 16k vocab (kendi BPE'miz)
    tok_dir = "/kaggle/working/tok16k"
    if not os.path.exists(tok_dir + "/vocab.json"):
        from model.tokenizer.bpe import BPE

        def texts():
            with open(raw) as f:
                chunk = f.read(4 << 20)
                while chunk:
                    yield chunk
                    chunk = f.read(4 << 20)
        BPE().train(texts(), vocab_size=16000, min_freq=3,
                    progress=lambda s, n: print(f"merge {s}/{n}", flush=True)
                    ).save(tok_dir)

    # 3) Ön-tokenleme
    shards = "/kaggle/working/shards"
    if not os.path.exists(shards + "/index.json"):
        from model.tokenizer.bpe import BPE as _B
        from model.data.pretokenize import pretokenize_stream
        tok = _B.load(tok_dir)

        def stream():
            with open(raw) as f:
                chunk = f.read(8 << 20)
                while chunk:
                    yield chunk
                    chunk = f.read(8 << 20)
        pretokenize_stream(stream(), tok, shards, shard_tokens=8_000_000)

    # 4) Eğitim — resume'lu
    resume = "--resume" if RESUME else ""
    sh(f"python -m model.pretrain --preset {PRESET} --data {shards} "
       f"--tokenizer {tok_dir} --out /kaggle/working/runs/{PRESET} "
       f"--steps {STEPS} --batch 8 --accum 8 --seq 512 --lr 3e-4 "
       f"--ckpt_every 500 --sample_every 2000 --device {DEVICE} {resume}")

    # 5) Değerlendirme
    sh(f"python -m model.eval --ckpt /kaggle/working/runs/{PRESET}/last "
       f"--tokenizer {tok_dir} --out /kaggle/working/eval_{PRESET}.json --device cuda")


if __name__ == "__main__":
    main()
